typedef struct
{
    _Bool valid;
    size_t next_offset;
} utf8_char_validity;

functions.validate_utf8_char:
utf8_char_validity validate_utf8_char(const char *str, size_t offset)
{
    if (((uint8_t)str[offset] & 0b10000000) == 0b00000000)
        return (utf8_char_validity){.valid = 1, .next_offset = offset + 1};
    if (((uint8_t)str[offset + 0] & 0b11100000) == 0b11000000 && ((uint8_t)str[offset + 1] & 0b11000000) == 0b10000000)
    {
        if (((uint8_t)str[offset] & 0b00011111) < 0b00000010)
            return (utf8_char_validity){.valid = 0, .next_offset = offset};
        return (utf8_char_validity){.valid = 1, .next_offset = offset + 2};
    }
    if (((uint8_t)str[offset + 0] & 0b11110000) == 0b11100000 &&
        ((uint8_t)str[offset + 1] & 0b11000000) == 0b10000000 && ((uint8_t)str[offset + 2] & 0b11000000) == 0b10000000)
    {
        if (((uint8_t)str[offset + 0] & 0b00001111) == 0b00000000 &&
            ((uint8_t)str[offset + 1] & 0b00111111) < 0b00100000)
            return (utf8_char_validity){.valid = 0, .next_offset = offset};
        if ((uint8_t)str[offset + 0] == 0b11101101 && (uint8_t)str[offset + 1] >= 0b10100000 &&
            (uint8_t)str[offset + 1] <= 0b10111111)
            return (utf8_char_validity){.valid = 0, .next_offset = offset};
        return (utf8_char_validity){.valid = 1, .next_offset = offset + 3};
    }
    if (((uint8_t)str[offset + 0] & 0b11111000) == 0b11110000 &&
        ((uint8_t)str[offset + 1] & 0b11000000) == 0b10000000 &&
        ((uint8_t)str[offset + 2] & 0b11000000) == 0b10000000 && ((uint8_t)str[offset + 3] & 0b11000000) == 0b10000000)
    {
        if (((uint8_t)str[offset + 0] & 0b00000111) == 0b00000000 &&
            ((uint8_t)str[offset + 1] & 0b00111111) < 0b00010000)
            return (utf8_char_validity){.valid = 0, .next_offset = offset};
        return (utf8_char_validity){.valid = 1, .next_offset = offset + 4};
    }
    return (utf8_char_validity){.valid = 0, .next_offset = offset};
}

functions.validate_utf8:
utf8_validity validate_utf8(const char *str)
{
    if (str == ((void *)0))
        return (utf8_validity){.valid = 0, .valid_upto = 0};
    size_t offset = 0;
    utf8_char_validity char_validity;
    while (str[offset] != '\0')
    {
        char_validity = validate_utf8_char(str, offset);
        if (char_validity.valid)
            offset = char_validity.next_offset;
        else
            return (utf8_validity){.valid = 0, .valid_upto = offset};
    }
    return (utf8_validity){.valid = 1, .valid_upto = offset};
}

functions.make_utf8_string:
utf8_string make_utf8_string(const char *str)
{
    utf8_validity validity = validate_utf8(str);
    if (validity.valid)
        return (utf8_string){.str = str, .byte_len = validity.valid_upto};
    return (utf8_string){.str = ((void *)0), .byte_len = 0};
}

functions.make_utf8_string_lossy:
owned_utf8_string make_utf8_string_lossy(const char *str)
{
    if (str == ((void *)0))
        return (owned_utf8_string){.str = ((void *)0), .byte_len = 0};
    size_t len = strlen(str);
    size_t worst_case_size = len * 3 + 1;
    char *buffer = (char *)malloc(worst_case_size);
    if (!buffer)
        return (owned_utf8_string){.str = ((void *)0), .byte_len = 0};
    size_t buffer_offset = 0;
    size_t offset = 0;
    utf8_char_validity char_validity;
    while (offset < len)
    {
        char_validity = validate_utf8_char(str, offset);
        if (char_validity.valid)
        {
            size_t char_len = char_validity.next_offset - offset;
            memcpy(buffer + buffer_offset, str + offset, char_len);
            buffer_offset += char_len;
            offset = char_validity.next_offset;
        }
        else
        {
            buffer[buffer_offset++] = 0xEF;
            buffer[buffer_offset++] = 0xBF;
            buffer[buffer_offset++] = 0xBD;
            offset++;
        }
    }
    buffer[buffer_offset] = '\0';
    return (owned_utf8_string){.str = buffer, .byte_len = buffer_offset};
}

functions.as_utf8_string:
utf8_string as_utf8_string(const owned_utf8_string *owned_str)
{
    return (utf8_string){.str = owned_str->str, .byte_len = owned_str->byte_len};
}

functions.free_owned_utf8_string:
void free_owned_utf8_string(owned_utf8_string *owned_str)
{
    if (owned_str->str)
    {
        free(owned_str->str);
        owned_str->str = ((void *)0);
        owned_str->byte_len = 0;
    }
}

functions.slice_utf8_string:
utf8_string slice_utf8_string(utf8_string ustr, size_t start_byte_index, size_t byte_len)
{
    if (start_byte_index > ustr.byte_len)
        start_byte_index = ustr.byte_len;
    size_t excl_end_byte_index = start_byte_index + byte_len;
    if (excl_end_byte_index > ustr.byte_len)
        excl_end_byte_index = ustr.byte_len;
    if (is_utf8_char_boundary(ustr.str + start_byte_index) && is_utf8_char_boundary(ustr.str + excl_end_byte_index))
        return (utf8_string){.str = ustr.str + start_byte_index, .byte_len = excl_end_byte_index - start_byte_index};
    return (utf8_string){.str = ((void *)0), .byte_len = 0};
}

functions.next_utf8_char:
utf8_char next_utf8_char(utf8_char_iter *iter)
{
    if (*iter->str == '\0')
        return (utf8_char){.str = iter->str, .byte_len = 0};
    const char *curr_boundary = iter->str;
    iter->str++;
    uint8_t byte_len = 1;
    while (!is_utf8_char_boundary(iter->str))
    {
        iter->str++;
        byte_len++;
    }
    return (utf8_char){.str = curr_boundary, .byte_len = byte_len};
}

functions.nth_utf8_char:
utf8_char nth_utf8_char(utf8_string ustr, size_t char_index)
{
    utf8_char_iter iter = make_utf8_char_iter(ustr);
    utf8_char ch;
    while ((ch = next_utf8_char(&iter)).byte_len != 0 && char_index-- != 0)
    {
    }
    if (ch.byte_len == 0)
        return (utf8_char){.str = ((void *)0), .byte_len = 0};
    return ch;
}

functions.utf8_char_count:
size_t utf8_char_count(utf8_string ustr)
{
    utf8_char_iter iter = make_utf8_char_iter(ustr);
    size_t count = 0;
    while (next_utf8_char(&iter).byte_len > 0)
        count++;
    return count;
}

functions.unicode_code_point:
uint32_t unicode_code_point(utf8_char uchar)
{
    switch (uchar.byte_len)
    {
    case 1:
        return uchar.str[0] & 0b01111111;
    case 2:
        return (uchar.str[0] & 0b00011111) << 6 | (uchar.str[1] & 0b00111111);
    case 3:
        return (uchar.str[0] & 0b00001111) << 12 | (uchar.str[1] & 0b00111111) << 6 | (uchar.str[2] & 0b00111111);
    case 4:
        return (uchar.str[0] & 0b00000111) << 18 | (uchar.str[1] & 0b00111111) << 12 |
               (uchar.str[2] & 0b00111111) << 6 | (uchar.str[3] & 0b00111111);
    }
    return 0;
}
